Rules.InvariantScript:
// Update hours table
If(
    CountRows(colVacationsUpdates) > 0,
    Patch(
        'Vacations Tracking (Days)',
        ShowColumns(
            colVacationsUpdates,
            ID,
            Type_of_leave,
            ApprovalStatus_1,
            ApprovalStatus_2,
            Approver_Comments)
    )
);

ForAll(
    colVacationsUpdates,
    If(
        (ApprovalStatus_1 = "Approved") ||
        (ApprovalStatus_1 = "Rejected"), 
        Office365Outlook.SendEmailV2(
            Employee,
            Text(TypeofLeave) & " Request " & Text(ApprovalStatus_1),
            "A new " & Text(TypeofLeave) & " request has been " & Text(ApprovalStatus_1) & " by your manager. Please log in to your DayAway application to view the details and comments regarding your request." & "<br>" & "<br>" &
            "<b>Type of Leave:</b> " & Text(TypeofLeave) & "<br>" &
            "<b>Dates:</b> " & Text(StartDate, "[$-en-US]dd-mmm-yyyy") &
            " to " & Text(EndDate, "[$-en-US]dd-mmm-yyyy") & "<br>" &
            "<b>Comments:</b> " & Text(Approver_Comments),
            {
                Cc: ApproverID_1,
                IsHtml: true
            }
        )
    )
);


Clear(colVacationsUpdates);

// Notify user
Notify("Records updated successfully!", NotificationType.Success);

// Refresh the data source
Refresh('Vacations Tracking (Days)');

// Update hours table
If(
    CountRows(colVacationsUpdates) > 0,
    Patch(
        'Vacations Tracking (Days)',
        ShowColumns(
            colVacationsUpdates,
            ID,
            Type_of_leave,
            ApprovalStatus_1,
            ApprovalStatus_2,
            Approver_Comments)
    )
);

ForAll(
    colVacationsUpdates,
    If(
        (ApprovalStatus_1 = "Approved") ||
        (ApprovalStatus_1 = "Rejected"), 
        Office365Outlook.SendEmailV2(
            Employee,
            Text(TypeofLeave) & " Request " & Text(ApprovalStatus_1),
            "A new " & Text(TypeofLeave) & " request has been " & Text(ApprovalStatus_1) & " by your manager. Please log in to your DayAway application to view the details and comments regarding your request." & "<br>" & "<br>" &
            "<b>Type of Leave:</b> " & Text(TypeofLeave) & "<br>" &
            "<b>Dates:</b> " & Text(StartDate, "[$-en-US]dd-mmm-yyyy") &
            " to " & Text(EndDate, "[$-en-US]dd-mmm-yyyy") & "<br>" &
            "<b>Comments:</b> " & Text(Approver_Comments),
            {
                Cc: ApproverID_1,
                IsHtml: true
            }
        )
    )
);


Clear(colVacationsUpdates);

// Notify user
Notify("Records updated successfully!", NotificationType.Success);

// Refresh the data source
Refresh('Vacations Tracking (Days)');

// Max height if more than 13 rows

Min(556,
49 + 40 * CountRows(
SortByColumns(
    If(
        !IsBlank(
            LookUp(
                'Vacations Tracking (Permissions)',
                User_Email = User().Email,
                User_Email
            )
        ),
        // If user exists in Permissions list → show ALL entries
        Filter(
        'Vacations Tracking (Days)',
        (IsBlank(Dropdown_Crew_App.Selected.Value) || Employee_Name = Dropdown_Crew_App.Selected.Value) &&
        (IsBlank(DatePickerFrom_Date_App.SelectedDate) || StartDate >= DatePickerFrom_Date_App.SelectedDate) &&
        (IsBlank(DatePickerTo_Date_App.SelectedDate) || EndDate <= DatePickerTo_Date_App.SelectedDate)
        ),

        
        // Else → only entries where ApproverID_1 = current user
        Filter(
        'Vacations Tracking (Days)',
        ApproverID_1 = User().Email,
        (IsBlank(Dropdown_Crew_App.Selected.Value) || Employee_Name = Dropdown_Crew_App.Selected.Value)&&
        (IsBlank(DatePickerFrom_Date_App.SelectedDate) || StartDate >= DatePickerFrom_Date_App.SelectedDate) &&
        (IsBlank(DatePickerTo_Date_App.SelectedDate) || EndDate <= DatePickerTo_Date_App.SelectedDate)
        )
    ),
    "EndDate",
    SortOrder.Descending
)
    )
)

If(
    IsBlank(
        LookUp(
            colVacationsUpdates,
            ID = ThisItem.ID
        )
    ),
    Collect(
        colVacationsUpdates,
        {
            ID: ThisItem.ID,
            ApprovalStatus_1: Dropdown_Approval1_App.Selected.Value,
            Approver_Comments: TextInput_AppComment_App.Text
        }
    ),
    UpdateIf(
        colVacationsUpdates,
        ID = ThisItem.ID,
        {
            ApprovalStatus_1: Dropdown_Approval1_App.Selected.Value,
            Approver_Comments: TextInput_AppComment_App.Text
        }
    )
);
